import { simd as getSimd, relaxedSimd as getRelaxedSimd } from "wasm-feature-detect";
import { memoize } from "../common/memoize";
import type { Version } from "../common/version";
import { extractVersion, isVersionAtLeast } from "../common/version";
import type { XrCapabilities } from "../lens-core-module/generated-types";
import { platformNotSupportedError } from "../namedErrors";
import { getPlatformInfo } from "./platformInfo";

/** @internal */
export type SupportedCapability<T> = T & { supported: true };
/** @internal */
export type UnsupportedCapability = { supported: false; error: Error };
/** @internal */
export type Capability<T = void> = SupportedCapability<T> | UnsupportedCapability;

//-----------
// WebGL
//-----------

type WebGlCapability = Capability<{ maxTextureSize: number }>;

// This required minimum max texture size is based on data from
// https://web3dsurvey.com/webgl/parameters/MAX_TEXTURE_SIZE. Checking for a reasonable minimum MAX_TEXTURE_SIZE avoids
// attempting to run lenses on platforms that will not support them -- most commonly, we've seen some platforms that
// report 0 MAX_TEXTURE_SIZE, which will cause errors for all lenses.
const minRequiredMaxTextureSize = 1024;

/**
 * @returns An object with fields describing support for various WebGL features.
 *
 * @internal
 */
function getWebGlSupport(): WebGlCapability {
    const ctx = globalThis.document?.createElement("canvas").getContext("webgl2");
    if (!ctx) {
        const cause = globalThis.document?.createElement("canvas").getContext("webgl")
            ? "platform_not_supported_only_webgl1"
            : typeof globalThis.WebGLRenderingContext === "function"
            ? "platform_not_supported_likely_no_hw_accel"
            : "platform_not_supported_no_webgl_browser_support";
        return {
            supported: false,
            error: platformNotSupportedError(
                "CameraKit requires WebGL2, but this browser does not support WebGL2.",
                new Error(cause)
            ),
        };
    }
    const maxTextureSize = ctx.getParameter(ctx.MAX_TEXTURE_SIZE);
    const supported = maxTextureSize >= minRequiredMaxTextureSize;
    return supported
        ? { supported, maxTextureSize }
        : {
              supported,
              error: platformNotSupportedError(
                  `CameraKit requires WebGL's MAX_TEXTURE_SIZE exceed a minimum value of ` +
                      `${minRequiredMaxTextureSize}, but the browser's reported MAX_TEXTURE_SIZE is ${maxTextureSize}.`
              ),
          };
}

//-----------
// WASM
//-----------

export interface WasmFeatures {
    simd: boolean;
    relaxedSimd: boolean;
}

type WasmCapability = Capability<{
    wasmFeatures: WasmFeatures;
}>;

/**
 * WebKit started reporting WASM SIMD support in Safari 16.4, but LensCore encountered rendering bugs when using SIMD
 * builds there, so we disabled SIMD on WebKit entirely. WebKit stabilized the feature in the 26.4 release, so from that
 * version onwards we use SIMD builds of LensCore again.
 *
 * Safari's version number tracks the OS release it ships with, so this single minimum applies both to iOS/iPadOS
 * versions and to Safari versions.
 */
const minWebKitSimdVersion: Version = { major: 26, minor: 4 };

/**
 * `browser.version` holds Safari's `Version/` token when the userAgent string provides one. When it doesn't – as for
 * WebKit browsers other than Safari (e.g. Chrome, Firefox on iOS) and for embedded WebViews – {@link getPlatformInfo}
 * falls back to the WebKit build number from the `Safari/` token (e.g. `605.1.15`). When neither token is present it
 * reports the placeholder `0`, since it can identify neither a brand nor a version.
 *
 * Build numbers are far larger than any release version, so this threshold lets us tell the two apart – otherwise
 * `Safari/605.1.15` would compare as newer than 26.4 and we'd enable SIMD on WebKit versions we haven't verified.
 */
const maxKnownWebKitMajorVersion = 100;

/**
 * @returns True if `version` is a WebKit release version rather than a build number, the `0` placeholder, or an
 * unparseable value. WebKit has never shipped a major version `0`, so we reject it here and fall back to the OS version
 * rather than treating the placeholder as a real – and too old – release.
 */
function isWebKitReleaseVersion({ major }: Version): boolean {
    return !Number.isNaN(major) && major > 0 && major <= maxKnownWebKitMajorVersion;
}

/**
 * @returns True if `version` is a WebKit release version new enough to use SIMD builds of LensCore. Build numbers and
 * unparseable versions are treated as older, so that we fall back to the more conservative behavior.
 */
function isWebKitSimdVersion(version: Version): boolean {
    return isWebKitReleaseVersion(version) && isVersionAtLeast(version, minWebKitSimdVersion);
}

/**
 * LensCore is built in SIMD and non-SIMD flavors, and WebKit reports SIMD support in versions where LensCore cannot
 * reliably use it – see {@link minWebKitSimdVersion}.
 *
 * @returns True if SIMD builds of LensCore may be used on the current browser.
 *
 * @internal
 */
function canUseSimdBuilds(): boolean {
    const { browser, osName, osVersion } = getPlatformInfo();

    // Every browser on iOS and iPadOS is required to use WebKit. Everywhere else, Safari is the only WebKit browser.
    const isIos = osName === "ios" || osName === "ipados";
    if (!isIos && browser.brand !== "Safari") return true;

    // Safari's own version is the most precise signal available, so we use it whenever the userAgent provides one.
    const browserVersion = extractVersion(browser.version);
    if (isWebKitReleaseVersion(browserVersion)) return isWebKitSimdVersion(browserVersion);

    // For WebKit browsers which report no version of their own, the OS version is all we have left. It's only usable on
    // iOS/iPadOS – macOS freezes it in the userAgent string at 10_15_7 – and Apple has frozen it there too since the 26
    // release (an iOS 26.5 device reports `CPU iPhone OS 18_7`), so it can only ever under-report.
    return isIos && isWebKitSimdVersion(extractVersion(osVersion));
}

/**
 * @returns A non-negative integer representing the combination of supported WebAssembly features, or -1 if WebAssembly
 * is not supported at all.
 *
 * @internal
 */
async function getWebAssemblyCapabilities(): Promise<WasmCapability> {
    if (globalThis.WebAssembly === undefined)
        return {
            supported: false,
            error: platformNotSupportedError(
                "CameraKit requires WebAssembly, but this browser does not support WebAssembly."
            ),
        };
    const [simd, relaxedSimd] = await Promise.all([getSimd(), getRelaxedSimd()]);
    // Relaxed SIMD is a superset of SIMD, so both flavors are gated on the same check.
    const simdAllowed = canUseSimdBuilds();
    return {
        supported: true,
        wasmFeatures: {
            simd: simd && simdAllowed,
            relaxedSimd: relaxedSimd && simdAllowed,
        },
    };
}

//-----------
// WebXR
//-----------

type WebXrCapability = Capability<XrCapabilities>;

function getGenericWebXrNotSupported(cause?: unknown): WebXrCapability {
    return {
        supported: false,
        error: platformNotSupportedError(
            `Use of this feature requires WebXR support for immersive AR sessions, but ` +
                `this browser does not support immersive AR sessions.`,
            cause
        ),
    };
}

/**
 * @returns A Promise containing an object with fields describing the support of various WebXR features. This object's
 * type is defined by LensCore, as they consume these capabilities and adjust behavior accordingly.
 *
 * @internal
 */
export async function getWebXrCapabilities(): Promise<WebXrCapability> {
    try {
        if (!isSecureContext || !navigator.xr) return getGenericWebXrNotSupported();
        const isImmersiveArSupported = await navigator.xr.isSessionSupported("immersive-ar");
        return isImmersiveArSupported
            ? {
                  supported: true,
                  sixDofSupported: true,
                  sceneDepthSupported: true,
              }
            : getGenericWebXrNotSupported();
    } catch (error) {
        if (error instanceof Error && error.name === "SecurityError") {
            return {
                supported: false,
                error: platformNotSupportedError(
                    "Failed to check XR capabilities due to permissions or other issues.",
                    error
                ),
            };
        }
        return getGenericWebXrNotSupported(error);
    }
}

/** @internal */
export interface PlatformCapabilities {
    webgl: WebGlCapability;
    wasm: WasmCapability;
    webxr: WebXrCapability;
}

/**
 * Get information about the current platform capabilities, including:
 * - WebGL support and various WebGL parameters.
 * - WASM support and support for various WASM features.
 * - WebXR support and support for various WebXR features.
 *
 * @internal
 */
export const getPlatformCapabilities = memoize(async function getPlatformCapabilities(): Promise<PlatformCapabilities> {
    return {
        webgl: getWebGlSupport(),
        wasm: await getWebAssemblyCapabilities(),
        webxr: await getWebXrCapabilities(),
    };
});
